"""Emit lean/TinyCryptids/ZeroFree/Machine.lean (the design) and Codes.lean (the digit
codes A and B as Lean functions) from build.py."""
import os, sys
sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'tools'))
import leangen, build
print(leangen.machine_lean('zerofree.txt', 'ZeroFree'), 'states written')
b = lambda ch: 'true' if ch == '1' else 'false'
L = ['import TinyCryptids.ZeroFree.Spec', '',
     '/-! The digit codes of `build.py`, generated by `gen_lean.py`. A decimal digit `d = 2a + b`',
     'takes the parity `b`, then the three cells of code A of `a` (between rounds), or of code B,',
     'which the pass writes from the old digit (`B[d mod 2, d / 2]`). -/', '',
     'namespace TM.ZeroFree', '', 'open D', '']
for i, nm in enumerate('xyz'):
    L += [f'/-- cell {nm} of code A of digit `d` (of `a = d / 2`) -/', f'def a{nm} : D → Bool']
    L += [f'  | d{d} => {b(build.A[d // 2][i])}' for d in range(10)] + ['']
for i, nm in enumerate('xyz'):
    L += [f'/-- cell {nm} of code B written for the old digit `d` -/', f'def q{nm} : D → Bool']
    L += [f'  | d{d} => {b(build.BETA[f"{d % 2}{d // 2}"][i])}' for d in range(10)] + ['']
L += ['end TM.ZeroFree', '']
out = os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'lean', 'TinyCryptids', 'ZeroFree', 'Codes.lean')
open(out, 'w').write('\n'.join(L))
